@Builder
  private topBar() {
    AppTopBar({ title: '书架' }) {
      Row({ space: 18 }) {
        ReaderIconButton({
          icon: (this.appThemeScheme === 'night' ? $r('app.media.bookshelf_search_theme_night') : $r('app.media.bookshelf_search')),
          boxSize: 44,
          iconSize: 24,
          radius: 22,
          onTap: (): void => this.onSearchRequested(),
        });

        // V1 ordinary callbacks are constructor inputs. Only this temporary
        // trigger gets a fresh identity; bookshelf content/scroll stay mounted.
        ForEach([this.navigationGeneration], (_generation: number) => {
          ReaderIconButton({
            icon: (this.appThemeScheme === 'night' ? $r('app.media.bookshelf_more_theme_night') : $r('app.media.bookshelf_more')),
            boxSize: 44,
            iconSize: 44,
            radius: 22,
            onTap: this.moreOpenAction(this.temporaryBackIdentity),
          })
            .accessibilityText('更多')
            .onAreaChange((_oldValue: Area, newValue: Area): void => {
              this.moreAnchorRight = Number(newValue.globalPosition.x) + Number(newValue.width);
              this.moreAnchorBottom = Number(newValue.globalPosition.y) + Number(newValue.height);
            });
        }, (generation: number): string => generation.toString());
      }
    }
  }

@Builder
  private homeTopBar() {
    AppTopBar({ title: '发现' }) {
      ReaderIconButton({
        icon: (this.appThemeScheme === 'night' ? $r('app.media.discover_refresh_theme_night') : $r('app.media.discover_refresh')),
        boxSize: 44,
        iconSize: 24,
        radius: 22,
        onTap: (): void => this.onRefresh(),
      });
    }
  }

@Builder
  private searchBar() {
    Row({ space: TOK_SPACE_CONTROL_INLINE }) {
      ReaderIconButton({ icon: (this.appThemeScheme === 'night' ? $r('app.media.search_back_theme_night') : $r('app.media.search_back')),
        boxSize: 32, iconSize: 20, radius: 16, onTap: (): void => this.onBack() });

      Row() {
        ReaderSearchField({
          variant: 'bookPage',
          mode: 'submit',
          focusOnAppear: this.focusInputOnAppear,
          text: this.keyword,
          placeholder: '搜索书名、作者...',
          accessibilityLabel: '搜索书名或作者',
          isTablet: this.isTablet,
          clearable: true,
          submitEnabled: this.presentation.kind !== 'loading',
          onTextChange: (value: string): void => {
            this.keyword = value;
            this.viewState.keywordDraft = value;
          },
          onSubmit: (): void => this.submitSearch(),
        });
      }
      .layoutWeight(1)
      .height(this.isTablet ? 40 : 36)
      .alignItems(VerticalAlign.Center);

      // The search action doubles as the ACQ-02 stop control: while a sweep
      // is live the pill reads 停止 and stops the sweep; otherwise it submits.
      // Loading additionally inlines a 13px spinner and submitSearch prevents
      // re-entry.
      ReaderButton({ scheme: this.appThemeScheme, specId: this.isTablet ? 'search-field-wide' : 'search-field-phone',
        label: this.isSweeping() ? '停止' : '搜索', isBusy: this.isSweeping(), actionEnabled: this.canSubmit(),
        leading: (): void => this.searchActionLeading(),
        onAction: (): void => { if (this.isSweeping()) this.onStop(); else this.submitSearch(); } });
    }
    .width(this.contentFrame().width)
    .height(this.isTablet ? 56 : 52)
    .padding({ left: this.isTablet ? 20 : TOK_SPACE_MD, right: this.isTablet ? 20 : TOK_SPACE_MD, top: TOK_SPACE_XS })
    .alignItems(VerticalAlign.Center)
    .hitTestBehavior(HitTestMode.Transparent);
  }

@Builder
  private backBar() {
    PageBackBar({
      title: '书源管理',
      onBack: (): void => this.onBack(),
    }) {
      ReaderIconButton({ icon: this.appThemeScheme === 'night' ? $r('app.media.bookshelf_more_theme_night') : $r('app.media.bookshelf_more'),
        boxSize: 44, iconSize: 20, radius: 22, onTap: (): void => this.onOpenTools() });
    }
  }
